  [ [=[A mechanism that allows faster vertical travel without climbing]=] ] = [=[Механизм, который быстро поднимает и опускает — карабкаться не нужно]=],
  [ [=[Ancient Civ Fast Elevator Vertical]=] ] = [=[Древний быстрый подъемник]=],
  [ [=[Ancient Civ Elevator Vertical]=] ] = [=[Древний подъемник]=],
