  [ [=[Most poisons will be automatically cleansed while this buff is active]=] ] = [=[Пока действует этот эффект, большинство ядов снимается само]=],
  [ [=[Every 3 seconds, all Poisons are removed.]=] ] = [=[Каждые 3 секунды снимает все яды.]=],
