  [ [=[Khitan Ronin Pants]=] ] = [=[Кхитайские штаны ронина]=],
  [ [=[Odzutsu Rifle]=] ] = [=[Ружье-одзуцу]=],
  [ [=[A ranged musket that fires infinite Explosive Cartridges]=] ] = [=[Мушкет с бесконечным запасом взрывных патронов]=],
  [ [=[This larger than most matchlock called a Ōdzutsu "Big Pipe" seems to fire are a very large caliber almost one inch in diameter. It bears intricate Nihon style markings and a forge mark that reads 山本 (Yamamoto) and an odd Rune. Commission item.]=] ] = [=[Этот фитильный мушкет, крупнее большинства, зовется одзуцу — «большая труба» — и, похоже, стреляет пулями огромного калибра, почти дюйм в поперечнике. На нем затейливые знаки в стиле Нихон, клеймо кузницы с надписью 山本 (Ямамото) и странная руна. Сделано на заказ.]=],
  [ [=[Slower ]=] ] = [=[Медленнее]=],
  [ [=[Margravina Ultra Greatsword]=] ] = [=[Сверхтяжелый двуручный меч маркграфини]=],
  [ [=[A massive two handed sword imbued with Frostburn & Energizing Assault]=] ] = [=[Огромный двуручный меч со свойствами «Обморожение» и «Бодрящий натиск»]=],
  [ [=[(HA) Liaru's Radish Launcher]=] ] = [=[(HA) Редисомет Лиару]=],
