  [ [=[Crypt Foundation]=] ] = [=[Фундамент гробницы]=],
  [ [=[A square foundation piece made of Black Ice-Reinforced Wood ]=] ] = [=[Квадратная секция укрепленного черным льдом деревянного фундамента.]=],
  [ [=[Inverted Tiled Wedge Crypt Sloped Roof]=] ] = [=[Обратная угловая черепичная скатная крыша гробницы]=],
