  [ [=[Tiled Wedge Crypt Sloped Roof]=] ] = [=[Черепичная угловая скатная крыша гробницы]=],
  [ [=[Tiled Sloped Crypt Roof]=] ] = [=[Черепичная скатная крыша гробницы]=],
  [ [=[Crypt Wedge Foundation]=] ] = [=[Угол фундамента гробницы]=],
