  [ [=[Torturer's Talisman (Accessory)]=] ] = [=[Талисман мучителя (аксессуар)]=],
  [ [=[A trinket that deals additional damage when striking Afflicted targets]=] ] = [=[Безделушка: дополнительный урон по целям с недугом]=],
  [ [=[Torturer]=] ] = [=[Мучитель]=],
  [ [=[Feral Talisman (Accessory)]=] ] = [=[Талисман дикости (аксессуар)]=],
  [ [=[A trinket that restores Stamina when striking Afflicted targets]=] ] = [=[Безделушка: удары по целям с недугом восстанавливают запас сил]=],
