  [ [=[Commissioned by Lochiel.]=] ] = [=[Сделано по заказу Lochiel.]=],
  [ [=[(HA) (ToT Accessory) Ethereal Wing (L)]=] ] = [=[(HA) (аксессуар ToT) Призрачное крыло (L)]=],
  [ [=[(HA) (ToT Accessory) Dog Muzzle]=] ] = [=[(HA) (аксессуар ToT) Собачий намордник]=],
  [ [=[(HA) Shapeshift: Small Bat Demon]=] ] = [=[(HA) Превращение: малый демон-нетопырь]=],
  [ [=[Prevents combat & changes your form - emote with Crouch, Flight, or Weapon Drawn states]=] ] = [=[Меняет ваш облик и не дает сражаться. Эмоции — в приседе, в полете или с обнаженным оружием]=],
  [ [=[Commissioned by Lev.]=] ] = [=[Сделано по заказу Lev.]=],
  [ [=[Arcane Magic Circle]=] ] = [=[Круг тайной магии]=],
  [ [=[A magical circle]=] ] = [=[Магический круг]=],
  [ [=[Blood Magic Circle]=] ] = [=[Круг магии крови]=],
  [ [=[(HA) Universal Crafting Bench - Mastersmith]=] ] = [=[(HA) Универсальный верстак — мастер-кузнец]=],
  [ [=[A bench with nearly every recipe that discounts and speeds up crafts]=] ] = [=[Верстак почти со всеми рецептами: удешевляет и ускоряет создание предметов]=],
  [ [=[Grants items bonuses equal to having a Universal Mastersmith slotted, even if you don't have any thrall slotted. To get bonuses on armor, the container holding them needs to be reloaded (pull bracelet or relog if it is in your inventory)]=] ] = [=[Дает предметам те же бонусы, что и универсальный мастер-кузнец в верстаке, даже если в верстаке нет ни одного раба. Чтобы бонусы получили доспехи, перезагрузите контейнер, в котором они лежат (воспользуйтесь браслетом или перезайдите в игру, если доспехи в инвентаре)]=],
  [ [=[All Table Recipes]=] ] = [=[Все рецепты верстака]=],
  [ [=[Preserves Food]=] ] = [=[Сохраняет еду]=],
  [ [=[Etched Gladius]=] ] = [=[Гравированный гладий]=],
  [ [=[A one handed blade imbued with Plagued Strikes & Healing Finishers]=] ] = [=[Одноручный клинок со свойствами «Чумные удары» и «Исцеляющие добивания»]=],
  [ [=[Plagued Strikes (+2)]=] ] = [=[Чумные удары (+2)]=],
